import unittest
from candidate import fibfib

class TestFibFibSequence(unittest.TestCase):
    def test_base_cases_zero(self):
        self.assertEqual(fibfib(0), 0)

    def test_base_cases_one(self):
        self.assertEqual(fibfib(1), 0)

    def test_base_cases_two(self):
        self.assertEqual(fibfib(2), 1)

    def test_small_values(self):
        self.assertEqual(fibfib(3), 1)
        self.assertEqual(fibfib(4), 2)
        self.assertEqual(fibfib(5), 4)
        self.assertEqual(fibfib(6), 7)
        self.assertEqual(fibfib(7), 13)

    def test_larger_value(self):
        self.assertEqual(fibfib(10), 44)

    def test_even_larger_value(self):
        self.assertEqual(fibfib(15), 1711)

    def test_repeated_calls_deterministic(self):
        first = fibfib(12)
        second = fibfib(12)
        self.assertEqual(first, 504)
        self.assertEqual(second, 504)

    def test_non_integer_float_equivalent(self):
        self.assertEqual(fibfib(5.0), 4)
        self.assertEqual(fibfib(2.0), 1)

    def test_non_integer_string_type_error(self):
        with self.assertRaises(TypeError):
            fibfib("5")

    def test_none_input_type_error(self):
        with self.assertRaises(TypeError):
            fibfib(None)

    def test_negative_input_recursion_error(self):
        with self.assertRaises(RecursionError):
            fibfib(-1)

    def test_negative_input_just_below_zero_recursion_error(self):
        with self.assertRaises(RecursionError):
            fibfib(-5)

    def test_boundary_upper_limit_small_value(self):
        self.assertEqual(fibfib(20), 36504)

    def test_zero_plus_one_edge(self):
        self.assertEqual(fibfib(0 + 1), 0)

    def test_sequence_monotonicity_up_to_ten(self):
        previous = fibfib(0)
        for n in range(1, 11):
            current = fibfib(n)
            self.assertGreaterEqual(current, previous)
            previous = current

    def test_large_value_within_recursion_limit(self):
        self.assertEqual(fibfib(22), 927)

    def test_non_integer_complex_number_error(self):
        with self.assertRaises(TypeError):
            fibfib(3 + 4j)

if __name__ == "__main__":
    unittest.main()
